// Extracts the contract spec entries from the built Wasm (K4) and writes them
// to packages/sdk/src/generated as base64 strings.
//
// Usage: node scripts/extract-spec.mjs [--check]
//
// Build the contracts first with `stellar contract build`. With --check,
// nothing is written, and the script exits 1 if a generated file differs from
// what it would write.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Spec } from '@stellar/stellar-sdk/contract';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const wasmDir = join(root, 'target', 'wasm32v1-none', 'release');
const outDir = join(root, 'packages', 'sdk', 'src', 'generated');

const contracts = [
  {
    wasm: 'loktin_target_savings.wasm',
    file: 'target-savings-spec.ts',
    name: 'targetSavingsSpec',
  },
  {
    wasm: 'loktin_spend_save.wasm',
    file: 'spend-save-spec.ts',
    name: 'spendSaveSpec',
  },
];

const check = process.argv.slice(2).includes('--check');
let differs = false;

for (const contract of contracts) {
  const spec = Spec.fromWasm(readFileSync(join(wasmDir, contract.wasm)));
  const lines = spec.entries.map((entry) => `  '${entry.toXdr('base64')}',`);
  const source = [
    '// Generated by scripts/extract-spec.mjs from the contract build. Do not edit.',
    `export const ${contract.name}: readonly string[] = [`,
    ...lines,
    '];',
    '',
  ].join('\n');

  const path = join(outDir, contract.file);
  const shown = relative(root, path);
  if (check) {
    let current = '';
    try {
      current = readFileSync(path, 'utf8');
    } catch {
      // A missing file counts as a difference.
    }
    if (current === source) {
      console.log(`${shown} is up to date`);
    } else {
      console.log(`${shown} differs from the contract build`);
      differs = true;
    }
  } else {
    writeFileSync(path, source);
    console.log(`wrote ${shown} (${String(spec.entries.length)} entries)`);
  }
}

if (differs) {
  console.log(
    'Run `node scripts/extract-spec.mjs` after `stellar contract build` and commit the result.',
  );
  process.exit(1);
}
